def resolve(path, cwd, links):
    # Normalize path into components
    if path.startswith('/'):
        current = ''
    else:
        current = cwd

    # Split path into components, removing empty ones and '.'
    components = [c for c in path.split('/') if c and c != '.']

    link_count = 0

    i = 0
    while i < len(components):
        component = components[i]

        if component == '..':
            # Move to parent
            if current == '':
                current = ''
            else:
                current = current.rsplit('/', 1)[0]
        else:
            # Append component
            if current == '':
                current = '/' + component
            else:
                current = current + '/' + component

            # Check if this is a symlink
            if current in links:
                link_count += 1
                if link_count > 8:
                    return None

                target = links[current]

                # Parse remaining components
                remaining = components[i+1:]

                # Parse target into components
                if target.startswith('/'):
                    # Absolute target
                    current = ''
                    target_components = [c for c in target.split('/') if c and c != '.']
                else:
                    # Relative target - relative to directory containing the link
                    if current == '':
                        target_dir = ''
                    else:
                        target_dir = current.rsplit('/', 1)[0]
                    current = target_dir
                    target_components = [c for c in target.split('/') if c and c != '.']

                # Insert target components before remaining components
                components = target_components + remaining
                i = 0
                continue

        i += 1

    # Return result
    if current == '':
        return '/'
    else:
        return current

